import { readFileSync } from "node:fs";
import { connect } from "node:net";

import type { WidgetContext, WidgetFieldValue, WidgetMount, WidgetQueryResult } from "../_lib/widget_context";

// Who's on a Factorio server. The card folds back to the plain one while nobody is on.
//
// The server's console (RCON) answers /players online with who's on. The image starts the console
// with the password in config/rconpw, in the app's data folder, on port 27015; the script doesn't
// publish it, so it's reached at the container's own address on its compose network, which the
// HexOS container opens from the host's network and nothing off the box can. The game's name and
// limit are in config/server-settings.json (a limit of 0 is none). A box without the Docker socket,
// or a server whose console isn't up yet, keeps the plain card.

const DOCKER_SOCKET = "/var/run/docker.sock";
/** Docker and the console share the widget's 5 s timeout, so a stuck one reads as nobody on. */
const DOCKER_TIMEOUT_MS = 1500;
const RCON_TIMEOUT_MS = 2500;
const RCON_PORT = 27015;
/** The example settings' placeholder name, which isn't worth showing. */
const PLACEHOLDER_NAME = "Name of the game as it will appear in the game listing";

// The console's packet types (the Source RCON protocol Factorio speaks)
const LOGIN = 3;
const COMMAND = 2;
const LOGIN_ANSWER = 2;
/** Far above any answer this widget asks for; a longer one is a stream it shouldn't trust. */
const MAX_PACKET = 1 << 16;

/** The data folder, by its host path, since the chart mounts it at /factorio itself. A later copy's ends in -2. */
export const dataMount = (mounts: WidgetMount[]): WidgetMount | undefined =>
  mounts.find((m) => m.containerPath === "/factorio") ?? mounts.find((m) => /\/factorio(-\d+)?\/data$/.test(m.hostPath));

/** The names in /players online's answer: "Online players (2):\n  alex (online)\n  sam (online)". */
export function onlinePlayers(answer: string): string[] {
  return answer
    .split("\n")
    .map((line) => /^\s+(.+?) \(online\)\s*$/.exec(line)?.[1])
    .filter((name): name is string => !!name);
}

/** The game's name and limit from server-settings.json. */
export function gameSettings(text: string | null): { name: string; max: number } {
  try {
    const settings = JSON.parse(text ?? "{}") as { name?: unknown; max_players?: unknown };
    const name = typeof settings.name === "string" && settings.name.trim() && settings.name !== PLACEHOLDER_NAME ? settings.name.trim() : "Factorio";
    return { name, max: Number(settings.max_players) || 0 };
  } catch {
    return { name: "Factorio", max: 0 };
  }
}

/** Who's online in a line: "Alex, Steve, and 3 more". */
export function playersLine(names: string[]): string {
  if (names.length <= 2) return names.join(" and ");
  if (names.length === 3) return `${names[0]}, ${names[1]}, and ${names[2]}`;
  return `${names[0]}, ${names[1]}, and ${names.length - 2} more`;
}

function packet(id: number, type: number, body: string): Buffer {
  const payload = Buffer.from(body, "utf8");
  // Length counts the id, the type, the body and its two closing zero bytes
  const out = Buffer.alloc(14 + payload.length);
  out.writeInt32LE(10 + payload.length, 0);
  out.writeInt32LE(id, 4);
  out.writeInt32LE(type, 8);
  payload.copy(out, 12);
  return out;
}

/** Signs in to the console and asks one command: its answer, or null when it can't. */
export function rcon(host: string, port: number, password: string, command: string, timeoutMs = RCON_TIMEOUT_MS): Promise<string | null> {
  return new Promise((resolve) => {
    const socket = connect({ host, port });
    let buffer = Buffer.alloc(0);
    let signedIn = false;
    const finish = (value: string | null) => {
      clearTimeout(timer);
      socket.destroy();
      resolve(value);
    };
    const timer = setTimeout(() => finish(null), timeoutMs);
    socket.on("error", () => finish(null));
    socket.on("close", () => finish(null));
    socket.on("connect", () => socket.write(packet(1, LOGIN, password)));
    socket.on("data", (chunk: Buffer) => {
      buffer = Buffer.concat([buffer, chunk]);
      while (buffer.length >= 4) {
        const length = buffer.readInt32LE(0);
        if (length < 10 || length > MAX_PACKET) return finish(null);
        if (buffer.length < 4 + length) return;
        const id = buffer.readInt32LE(4);
        const type = buffer.readInt32LE(8);
        const body = buffer.subarray(12, 2 + length).toString("utf8");
        buffer = buffer.subarray(4 + length);
        if (!signedIn) {
          if (type !== LOGIN_ANSWER) continue;
          if (id === -1) return finish(null);
          signedIn = true;
          socket.write(packet(10, COMMAND, command));
        } else if (id === 10) {
          return finish(body);
        }
      }
    });
  });
}

async function docker(path: string): Promise<Response | null> {
  try {
    const response = await fetch(`http://docker${path}`, { unix: DOCKER_SOCKET, signal: AbortSignal.timeout(DOCKER_TIMEOUT_MS) });
    return response.ok ? response : null;
  } catch {
    return null; // a box with no socket yet
  }
}

/** The container's address on its compose network, since a later copy's project is ix-factorio-2. */
async function containerAddress(appId: string): Promise<string | null> {
  const filters = encodeURIComponent(JSON.stringify({ label: [`com.docker.compose.project=ix-${appId}`], status: ["running"] }));
  const listed = (await (await docker(`/containers/json?filters=${filters}`))?.json().catch(() => null)) as
    | Array<{ NetworkSettings?: { Networks?: Record<string, { IPAddress?: string }> } }>
    | null;
  return Object.values(listed?.[0]?.NetworkSettings?.Networks ?? {}).map((network) => network.IPAddress).find(Boolean) ?? null;
}

const readText = (path: string): string | null => {
  try {
    return readFileSync(path, "utf8");
  } catch {
    return null;
  }
};

export async function run(ctx: WidgetContext): Promise<WidgetQueryResult> {
  const data = dataMount(ctx.mounts);
  const { name, max } = gameSettings(data ? readText(`${data.localPath}/config/server-settings.json`) : null);
  const password = data ? readText(`${data.localPath}/config/rconpw`)?.trim() : undefined;
  const address = password ? await containerAddress(ctx.appId) : null;
  const answer = password && address ? await rcon(address, RCON_PORT, password, "/players online") : null;
  const names = answer ? onlinePlayers(answer) : [];
  const fields: Record<string, WidgetFieldValue> = {
    // One entry while anyone's on: the game's name in bold, the players in the small line under it
    online: { type: "list", entries: names.length ? [{ title: name, subtitle: playersLine(names), image: ARTWORK }] : [] },
    count: { type: "stat", label: "Players", value: max ? `${names.length}/${max}` : `${names.length}` },
  };
  return { fields };
}

// Factorio's key art, from Aaron (2026-11-07): cropped to the card's shape toward its center, 660x260, WebP at quality 66 to fit the platform's 60,000-character cap.
export const ARTWORK =
  "data:image/webp;base64,";
